def join(arr, s):
  res = []
  for i in range(len(arr)):
    if i != 0:
      for c in s:
        res.append(c)
    for c in arr[i]:
      res.append(c)
  return array_to_string(res)

def array_to_string(arr):
  # Function allowed by the problem statement.
  return ''.join(arr)

